<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue';import {useApplication} from '../../application';import {stateLabels} from './workbench-types';
const props=defineProps<{module:'datasets'|'candidates'|'evaluations';modelValue:string;label:string;state?:string;disabled?:boolean}>(),emit=defineEmits<{'update:modelValue':[string]}>(),app=useApplication();
type Row={id:string;title:string;state:string};type Page={items:Row[];nextCursor:string|null};
const items=ref<Row[]>([]),cursor=ref<string|null>(null),query=ref(''),busy=ref(false),error=ref(''),selected=ref<Row|null>(null);let epoch=0;
async function load(next=false){const turn=++epoch;busy.value=true;error.value='';const q=new URLSearchParams({limit:'20'});if(query.value.trim())q.set('q',query.value.trim());if(props.state)q.set('state',props.state);if(next&&cursor.value)q.set('cursor',cursor.value);try{const page=await app.operationsCommands.read<Page>(`/api/v1/operations/${props.module}/page?${q}`);if(turn!==epoch)return;items.value=page.items;cursor.value=page.nextCursor;}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'选项暂不可用。';}finally{if(turn===epoch)busy.value=false;}}
function choose(event:Event){const id=(event.target as HTMLSelectElement).value;selected.value=items.value.find(r=>r.id===id)??null;emit('update:modelValue',id);}
watch(()=>[props.module,props.state,app.session.current.value?.actor.enterpriseId,app.operationsCommands.available.value],()=>{items.value=[];selected.value=null;if(app.operationsCommands.available.value)void load();},{immediate:true});onUnmounted(()=>epoch++);
</script>
<template><div class="gov-fields"><label>{{label}}<select :aria-label="label" :value="modelValue" :disabled="disabled||busy" @change="choose"><option value="">请选择</option><option v-if="selected&&!items.some(r=>r.id===selected!.id)" :value="selected.id">{{selected.title}}</option><option v-for="row in items" :key="row.id" :value="row.id">{{row.title}} · {{stateLabels[row.state]??row.state}}</option></select></label><div class="picker-search"><input v-model="query" :aria-label="'查找'+label" placeholder="按名称查找" maxlength="100" :disabled="disabled" @keydown.enter.prevent="load()"/><button type="button" class="btn sm" :disabled="disabled||busy" @click="load()">查找</button><button type="button" class="btn sm" :disabled="disabled||busy||!cursor" @click="load(true)">更多</button></div><p v-if="error" class="gov-error" role="alert">{{error}}</p></div></template>
<style scoped>.picker-search{display:flex;gap:6px;margin-top:-9px}.picker-search input{flex:1;min-width:0;padding:7px 10px;font-size:11px}.picker-search .btn{flex-shrink:0}</style>
